require 'includes/functions.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare("SELECT p.*,c.name category_name,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_main DESC,id LIMIT 1) image_path FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.status='active'");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Produit introuvable. <a href="shop.php">Retour</a>');}
$title=$p['name'];$base='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$q=max(1,min((int)$p['stock'],(int)($_POST['quantity']??1)));if($q<1)flash('Produit indisponible.','warning');else{$_SESSION['cart'][$id]=min((int)$p['stock'],($_SESSION['cart'][$id]??0)+$q);flash('Produit ajouté au panier.');}go('cart.php');}
require 'includes/header.php';?><section class="container section detail"><div class="detailimg"><img src="<?=e(img($p))?>" alt="<?=e($p['name'])?>"></div><div><small><?=$p['category_name']?> · <?=e($p['brand'])?></small><h1><?=e($p['name'])?></h1><h2><?=money($p['price'])?></h2><p><?=nl2br(e($p['description']))?></p><p class="green"><?=((int)$p['stock']>0)?'En stock : '.(int)$p['stock']:'Rupture de stock'?></p><?php if((int)$p['stock']>0):?><form method="post" class="add"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Quantité <input type="number" name="quantity" min="1" max="<?=(int)$p['stock']?>" value="1"></label><button class="btn">AJOUTER AU PANIER</button></form><?php endif?><p>✓ Paiement à la livraison · ✓ Livraison en Tunisie</p></div></section><?php require 'includes/footer.php';?>
